class CallbackHandler {
    int state = 100;
public:
    using CB_Sig = int(int);

    int execute(int input) const { return input + state; }

    // Member Function Pointer Type
    using MFP = CB_Sig (CallbackHandler::*);

    // Conversion Operator: Object -> Member Function Pointer
    operator MFP() const { return &CallbackHandler::execute; }
};

// Usage
CallbackHandler cb;
CallbackHandler::MFP fp = cb;
int result = (cb.*fp)(5); // Invokes execute(5), result = 105

// Conversion into a template context
template <typename T>
void run_callback(T handler) {
    // T is implicitly converted to MFP type
    (cb.*handler)(1);
}
